INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Toy Generals', 'Toy soldiers! Prepare for battle! The house is full of enemies and we must drive them out! Sniper - get in position! Grenadier - your target is the tower. Infantry - attack! Check every nook and cranny, battle the enemy in the attic, in the garden, up in the treehouse. Build up your unique squad and take back the house!' FROM games WHERE igdb_id = 90432 ON CONFLICT (game_id, language_code) DO NOTHING;
