INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dabwoman-when-the-dab-isnt-sexist', 106622, '2018-08-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobs16.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/zlxk4nkpet5f9kv3gyvz.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dabwoman: When the Dab isn''t Sexist', 'What is Dabwoman? Do I really need to explain this? I guess so, because I need a description. Well, Dabwoman is the best super hero video game ever made, want to argue on that? Alright, we are going to meet behind the school in 2 hours. You want to know the story? Alright, well it''s a woman, and she eats a laundry pod for no reason what so ever, and guess what? She becomes a super hero, you gotta admit that''s pretty dope. I''m not going to tell you the whole story, so just play the game man. It''s like a movie, but interactive, go make some popcorn and play it, if you don''t play it.. then you are a bully. Being a bully is bad.' FROM games WHERE igdb_id = 106622 ON CONFLICT (game_id, language_code) DO NOTHING;
