INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tale of Toast', 'With its easy to pick up play style, open world player versus player with high stakes for those daring to partake, and its focus on simple yet tactical combat, social aspects, trade skills, procedurally generated dungeons and quality over quantity quests, it is sure to have something for everyone.' FROM games WHERE igdb_id = 56147 ON CONFLICT (game_id, language_code) DO NOTHING;
