INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kingdom Come: Deliverance - Limited Edition', 'A humble, young blacksmith loses everything to war. As he tries to fulfill the dying wish of his father, Fate drags him into the thick of a conspiracy to save a kidnapped king and stop a bloody conflict. You will wander the world, fighting as a knight, lurking in the shadows as a rogue, or using the bard’s charm to persuade people to your cause.' FROM games WHERE igdb_id = 166176 ON CONFLICT (game_id, language_code) DO NOTHING;
