INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('my-brother-rabbit', 104522, '2018-09-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co21op.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arcfh.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Brother Rabbit', 'My Brother Rabbit is a beautifully drawn point-and-click adventure set in a surreal world that mixes reality with a child’s imagination. A loving family discovers that their daughter has fallen ill. While her parents set out to get her the treatment she needs, her determined older brother turns to the power of imagination to help both of them cope. While the outside world offers a harsh reality, these pure children envision a fantastic, surreal world that provides the innocent fun they deserve. Embark on a grand journey to five different lands filled with incredible robo-mooses, levitating baobabs, giant mushrooms, and clocks melting to the rhythm of passing time.' FROM games WHERE igdb_id = 104522 ON CONFLICT (game_id, language_code) DO NOTHING;
