INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ostalgie: The Berlin Wall', 'The confrontation between the East and the West is coming to an end, but not between East and West Germany. The old party leaders are still sitting in their offices, not changing anything and waiting for exclamations from Moscow. But their end is close – Gorbachev and Kohl have already decided...' FROM games WHERE igdb_id = 90250 ON CONFLICT (game_id, language_code) DO NOTHING;
