INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tomb Raider VR: Lara''s Escape', 'Become Lara Croft in Tomb Raider VR: Lara''s Escape, an interactive cinematic VR experience based on the upcoming Tomb Raider movie (March 2018). Pursued by Trinity soldiers, Lara Croft''s only means of escape is to descend into an ancient tomb. Use Lara''s flashlight to explore crumbling caverns in the dangerous, trap-filled cave. Wield Lara''s bow and climbing axe to escape capture as you rappel, climb and zip-line to safety.' FROM games WHERE igdb_id = 322639 ON CONFLICT (game_id, language_code) DO NOTHING;
