INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bottle of truth', 'Узнайте историю простого русского парня, который живет в России. Возможно он хотел бы никогда не покидать свое комфортное убежище и не видеть все ужасы улицы, но судьба уготовила ему совсем иные планы и ему предстоит увлекательное приключение.' FROM games WHERE igdb_id = 107975 ON CONFLICT (game_id, language_code) DO NOTHING;
