INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Caribbean Sea Fishes', 'Caribbean Sea Fishes is an authentic underwater photo hunting simulator. Play as a professional underwater photographer who is traveling in search of the best pictures for his magazine. You will see more than 40 species of beautiful Caribbean fish, as well as dangerous sharks and morays. Caribbean Sea Fishes is an opportunity to dive in various different corners of the ocean world and shoot fabulous photographs - and with money you will get form their sale you could purchase a more advanced diving kit!' FROM games WHERE igdb_id = 25503 ON CONFLICT (game_id, language_code) DO NOTHING;
