INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'What Isn''t Saved (will be lost)', 'Zoe is a neuroscientist who''s researching methods of resurrecting the dead… by rebuilding them from their memories. When her girlfriend Sara dies, Zoe uses her experimental technology to save her - but there isn''t enough room to save all of Sara''s memories. You must choose which ones will be saved, and which ones will be lost.' FROM games WHERE igdb_id = 135316 ON CONFLICT (game_id, language_code) DO NOTHING;
