INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Earth is a Better Person than Me', 'the earth is a better person than me is a visual novel following a young woman, Delphine, who runs away from her life and into a forest. She realizes she can talk to the earth around her; she has conversations with the moon about love, dirt about death, a tree about desire. Each path unearths a different aspect of Delphine''s life as she experiences sexuality, sex, self-image, and death.' FROM games WHERE igdb_id = 111335 ON CONFLICT (game_id, language_code) DO NOTHING;
