INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jack N'' Jill DX', 'In Jack N'' Jill DX, players must assume the role of Jack, overcoming many hazards, in a bid to reach Jill, who awaits him at the end of 140 levels, in typical old-school one-button platformer fashion! But, for the players who feel the guy should be the one who needs saving, we absolutely agree and that''s why Jill is available as a playable character as well! All you need to do, to play as her, is swap the graphics and hey presto, the change is complete.' FROM games WHERE igdb_id = 107044 ON CONFLICT (game_id, language_code) DO NOTHING;
