INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Detective Pikachu', 'Detective Pikachu is an adventure game developed by Creatures Inc., published by The Pokémon Company, and distributed by Nintendo for the Nintendo 3DS. The game is a spin-off of the Pokémon franchise, in which players work with a talking Pikachu to solve mysteries. A shorter, downloadable version of the game called Great Detective Pikachu: Birth of a New Duo was released in Japan in February 2016, while the full version was released worldwide in March 2018.' FROM games WHERE igdb_id = 81272 ON CONFLICT (game_id, language_code) DO NOTHING;
