INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lumines Remastered', 'Lumines Remastered brings minimalism to the puzzle genre where the fusion of light and sound sets the stage for a two-color falling block experience playable on-the-go on Nintendo Switch or at home in 4K on PC and consoles. Groove to electronic jams while strategically dropping blocks before the BPM bar sweeps combos clean after each measure. It’s a stylish game perfect to play anywhere or at anytime."' FROM games WHERE igdb_id = 94970 ON CONFLICT (game_id, language_code) DO NOTHING;
