INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Juicy Realm', 'Juicy Realm is a roguelike game in which players must square off against bizarre fruits all across the world. The line between the animal and the plant world has become blurred, and the food chain has been completely disrupted. Humans, upon making this incredible discovery, have set up outposts along the border of the aggressive plants'' habitat for investigations, defense, and in preparation for what may come. You take the role of a soldier on the front lines charged with confronting this strange new enemy.' FROM games WHERE igdb_id = 75263 ON CONFLICT (game_id, language_code) DO NOTHING;
