INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rusty Lake Paradise', '"Rusty Lake Paradise is set on a small remote island in the 18th Century. After your mother passed away the island seems to be cursed with the 10 plagues. It''s your job to go around the island, interact with your family and help them vanquish the plague. The game offers ominous situations and bizarre rituals. Paradise builds upon the distinctive atmosphere and excitement from the Rusty Lake series. For the background graphics we collaborated with a well-known Dutch artist, Johan Scherft."' FROM games WHERE igdb_id = 54678 ON CONFLICT (game_id, language_code) DO NOTHING;
