INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Lovely Daughter', 'My Lovely Daughter is a simulation game with elements borrowed from other works of fiction that involve alchemy as part of the narrative. The game want to focus on the idea that “life is not beautiful,” and the few things that can make it pretty are things like family and success. The game want to present the question of how far will you go to achieve them.' FROM games WHERE igdb_id = 74250 ON CONFLICT (game_id, language_code) DO NOTHING;
