INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trek: Travel Around the World', 'In Trek: Travel Around the World, the adventure starts in your new Helsinki apartment. Each experience after that transports you to a new destination where real-world locations are blended with magical phenomenon: Catching fishes in the Archipelago in order to fill the sky with the majestic Northern Lights, powering the city of Helsinki as a giant in the capital of Finland, and tracing the stars to highlight the constellations in the sky.' FROM games WHERE igdb_id = 105083 ON CONFLICT (game_id, language_code) DO NOTHING;
