INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hungry Piggy Donuts Mania', 'Our little kitties are under hungry to death. The most delicious food, donuts, are in font of kitty’ eyes. Find the best way to feed our hungry kitty! Hungry Kitty Donuts Mania features hours of gameplay, challenging physics-based puzzle, and lots of replay value. Each level requires logic and skill to resolve.' FROM games WHERE igdb_id = 105585 ON CONFLICT (game_id, language_code) DO NOTHING;
