INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mega Man 2: 30th Anniversary Classic Cartridge', 'The 30th Anniversary Classic Cartridge Edition of Mega Man 2 published by iam8bit is the original game on a brand-new playable NES cartridge in a tri-fold box w/ foil, gloss and embossments. Limited to a total of 8500 copies, of which 7500 copies come in Opaque Light Blue and 1000 copies come in Translucent, Glow-in-the-Dark Blue. The original manual has been worked over and includes mini posters. The tri-fold packaging doubles as a mini poster when opened up.' FROM games WHERE igdb_id = 196208 ON CONFLICT (game_id, language_code) DO NOTHING;
