INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MazeQuest 2', 'The King has been kidnapped, and the land of Reynard is under siege! Gather a party, and travel your way to different lands on a quest to re-seal an ancient evil. MazeQuest is a throwback to the 16 bit RPG era, with colorful 2d graphics and top-down turn based combat. The game is designed to be simple for casual players, but with rich storylines, and strategy to satisfy the most diehard RPG buffs!' FROM games WHERE igdb_id = 109641 ON CONFLICT (game_id, language_code) DO NOTHING;
