INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Overlook: Local multiplayer game up to 16 players', 'Overlook is a party game for up to 16 players using 8 gamepads! One player need only one hand and half of gamepad to play the game. Players split into two teams. You can play as an defective robot, where your goal is to destroy as many robots as you can, or you can play as an overseer to seek and find defective robots. Gameplay is heavily inspired by Hidden in Plain Sight. With Overlook we want to push Hidden in Plain Sight to the next level.' FROM games WHERE igdb_id = 78112 ON CONFLICT (game_id, language_code) DO NOTHING;
