INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Golf Club 2019 featuring PGA Tour', 'The Golf Club 2019 geaturing the PGA Tour is the sequel to the highly rated The Golf Club 2 and comes with a whole host of new and improved content and features across all aspects of the game, from a restructured Career mode experience, sponsors who challenge you and set you goals for a chance to earn rewards from licensed brand Under Armour. An improved character editor, new and improved online and solo societies, new game modes such as Skins and alt-shot as well as much, much more!' FROM games WHERE igdb_id = 91128 ON CONFLICT (game_id, language_code) DO NOTHING;
