INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aperion Cyberstorm', 'Aperion Cyberstorm is a 1-5 player 2D twin-stick shooter where combining your tools can save you, or scrap you. Salvage what’s left of your team against dangers in- and outside of the galaxy, and mix the abilities you find before you’re added to the heap; smash an enemy’s shields with electricity-imbued mines, before melting their hull with a spread of fire rockets.' FROM games WHERE igdb_id = 14385 ON CONFLICT (game_id, language_code) DO NOTHING;
