INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Life is Strange: Before the Storm - Limited Edition', 'Life is Strange: Before the Storm is a new three-part, standalone adventure set three years before the first game in the BAFTA award-winning franchise. You play as sixteen-year-old Chloe Price who forms an unlikely friendship with Rachel Amber, a beautiful and popular girl destined for success. When Rachel learns a secret about her family that threatens to destroy her world, it is her newfound friendship with Chloe that gives her the strength to carry on. No longer alone the girls must confront each other''s demons and together, find a way to overcome them.' FROM games WHERE igdb_id = 82432 ON CONFLICT (game_id, language_code) DO NOTHING;
