INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Resident Evil 7: Biohazard - Cloud', 'The Nintendo Switch version of Resident Evil 7: Biohazard was released some time after the original version. Next to the base game it comes with all available DLC which were previously commercial add-ons for the other platforms. The game itself is partially installed using only the basic & start-up files and is streamed through the Capcom online cloud servers, requiring a permanent internet connection.' FROM games WHERE igdb_id = 102075 ON CONFLICT (game_id, language_code) DO NOTHING;
