INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kanojo * Step', 'The protagonist has moved too many counts to count and this time, he has ended up in his grandmother’s minshuku located in Shirasagi, a rural town situated near the mountains. His sister told him that this was their last move, and after he graduates from school, he will be free to do as he wishes. After suppressing his feelings of love until now, he sets out to pursue his first love.' FROM games WHERE igdb_id = 139862 ON CONFLICT (game_id, language_code) DO NOTHING;
