INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Evie', 'Evie is a short first-person horror narrative that unfolds a mind-boggling event, set in the middle of an eerie forest that was left undiscovered for good reasons. The story starts off by reading diaries left in an abandoned house by a lady named Evie. As a player, you will quickly realize that great tragedies hit her life and uncontrollably fell into a downward spiral of despair.' FROM games WHERE igdb_id = 84017 ON CONFLICT (game_id, language_code) DO NOTHING;
