INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Anonymous ME', 'Anonymous Me is a 2D action platformer set in Qin Dynasty of China. Female assassin Meng Nv calls it quits after the organization she is in falls apart. Somehow she is plunged into a huge conspiracy. Players take the role of “Mang” and travels across China in Qin Dynasty and eliminate different enemies using cool combos, ultimately unraveling the mystery of this prosperous empire.' FROM games WHERE igdb_id = 68670 ON CONFLICT (game_id, language_code) DO NOTHING;
