INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Death Toll', 'Death Toll is a multiplayer, open world first person shooter that is part Royale and part Capture the Flag. Players are dropped into the world with nothing but their cunning, their will to survive, and the game''s single goal: Escape the Island. Death Toll features repairable combat vehicles, horses, wildlife and, of course, a wide variety of awesome weapons.' FROM games WHERE igdb_id = 74762 ON CONFLICT (game_id, language_code) DO NOTHING;
