INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('meet-the-miner-wdr-vr-bergwerk', 109319, '2018-09-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5ovx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arnzb.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Meet the Miner: WDR VR Bergwerk', 'Ever worked hundreds of meters beneath the earth, bent down in dark, narrow shafts, hitting coal out of the walls? Probably not. Now you can: The WDR, Germany’s largest public broadcaster, presents the interactive VR experience “Meet the Miner – WDR VR Bergwerk”. With an Oculus Rift, users can experience how dangerous and grueling life of a miner was 100 years ago – feeling what it was like racing down hundreds of meters into the earth in a shaky elevator and mining coal with a virtual pickaxe.' FROM games WHERE igdb_id = 109319 ON CONFLICT (game_id, language_code) DO NOTHING;
