INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Milanoir', 'Inspired by the Italian crime flicks of the ''70s revered by Quentin Tarantino, Milanoir is a pixel-packed action game set in the violent city of Milan. Come meet Piero, a convict suddenly released from prison looking for revenge over the man who framed him. Hunt for the truth and escape the ones who are chasing you through an unforgiving city. Someone wants you dead: you have to use all your toughness to survive. Shoot, choke, sneak your way through the enemies and engage them in breathtaking car chases.' FROM games WHERE igdb_id = 37852 ON CONFLICT (game_id, language_code) DO NOTHING;
