INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Detroit: Become Human', 'Detroit: Become Human is an interactive narrative adventure game developed by Quantic Dream and released in 2018. Set in a near-future Detroit where androids serve humans, the story follows three android protagonists—Kara, Connor, and Markus—who shape the city’s fate through their choices. Gameplay combines exploration, dialogue interactions, and quick-time events, with branching storylines and multiple endings. The narrative explores themes of artificial intelligence, freedom, and morality.' FROM games WHERE igdb_id = 14362 ON CONFLICT (game_id, language_code) DO NOTHING;
