INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SNK Heroines: Tag Team Frenzy', 'Play as iconic heroines from SNK’s history in a new, two-on-two tag-team fighting game. Players can activate a variety of Special Moves with the press of a button, and make use of special items to turn the tide of battle. One of the competitors will be Yuri Sakazaki from ACA NEOGEO Art of Fighting 2, which launches today in Nintendo eShop on Nintendo Switch. SNK HEROINES ~Tag Team Frenzy~ launches on Nintendo Switch this summer.' FROM games WHERE igdb_id = 81146 ON CONFLICT (game_id, language_code) DO NOTHING;
