INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('xenocite-clad', 64694, '2018-06-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co23uz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/rh3jwikse013fmhra3uo.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Xenocite Clad', 'Xenocite Clad places you in the long forgotten ruins of an advanced civilization that seemed to disappear overnight. Now, centuries later, the ruins have filled with life, both threatening and non. Brave the ruins against predators and more as you search for not only a way out, but the answers to the questions strewn all around you. Play as two heroines- Xalia the syr, using both an energy blade and an energy compressor drone, she seeks to learn more of her creators and their intentions this path will make her face the sins of her fathers and right them. ...and well you don''t need to know about the other one yet do you?' FROM games WHERE igdb_id = 64694 ON CONFLICT (game_id, language_code) DO NOTHING;
