INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'I''m on Observation Duty', 'Your job is to monitor live surveillance camera footage and spot anomalies in the monitored rooms. Anomalies range from furniture movement to otherworldly intruders. When you spot an anomaly you have to file a report to fix it. You will need sharp eyes and good memory to survive the entire night.' FROM games WHERE igdb_id = 116475 ON CONFLICT (game_id, language_code) DO NOTHING;
