INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Let''s Sing 2019', 'It’s your time to shine! The latest version of the singing game Let’s Sing features cutting-edge artists like Rita Ora with “Anywhere”, Shawn Mendes with “There’s Nothing Holdin’ Me Back”, DNCE with “Cake By The Ocean” and also legendary classics like ABBA with “Mamma Mia” or No Doubt with “Don’t Speak” are included in the track list. Also, international smashers like Martin Garrix & Dua Lipa with “Scared To Be Lonely”, Lorde with “Green Light” and with 30 international tracks on the playlist, Let’s Sing 2019 has something for everyone.' FROM games WHERE igdb_id = 110052 ON CONFLICT (game_id, language_code) DO NOTHING;
