INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('extinction', 36651, '2018-04-09', 52, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1ri9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4h9.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Extinction', 'As far back as anyone can remember, humanity has been at war with itself. For generations, kingdoms have fought amongst themselves while the real threat loomed in the distance. Legend calls them the Ravenii, encroaching armies of bloodthirsty monsters standing 150 feet tall that once threatened to destroy humankind. Now the threat has returned, and only those trained in the ways of the ancient order stand a chance at defeating the ogres. You are one of the world’s last Sentinels, a soldier named Avil equipped with the skills to battle the endless wave of Ravenii.
