INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spaceball', 'The game of the future is here! Did you ever wonder what sports would be like in space? This dynamic multiplayer game will have you on the edge of your seat for hours to come! Mixing elements of rugby with the low gravity of the moon, you can work as a team to score goals against your opponents. Tackle, grapple, and shoot your way to victory!' FROM games WHERE igdb_id = 145763 ON CONFLICT (game_id, language_code) DO NOTHING;
