INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'God of War', 'God of War is the sequel to God of War III as well as a continuation of the canon God of War chronology. Unlike previous installments, this game focuses on Norse mythology and follows an older and more seasoned Kratos and his son Atreus in the years since the third game. It is in this harsh, unforgiving world that he must fight to survive… and teach his son to do the same.' FROM games WHERE igdb_id = 19560 ON CONFLICT (game_id, language_code) DO NOTHING;
