INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kamen Rider: Climax Scramble', 'Kamen Rider: Climax Scramble, is a Japanese fighting game developed by Eighting and Bandai Namco Entertainment exclusively for the Nintendo Switch. Serving as the sequel to Kamen Rider: Climax Fighters, it is the second installment of the Climax Fighters reboot and the seventh overall installment of the Kamen Rider: Climax series. Celebrating the 20th anniversary of the franchise, the game features all the Riders within the Heisei-era that ended with Zi-O as playable characters.' FROM games WHERE igdb_id = 106307 ON CONFLICT (game_id, language_code) DO NOTHING;
