INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'CreativeDestruction', 'Creative Destruction is a FPS/TPS sandbox survival game that combines Battle Royale with a constructive concept. You will parachute onto a 4*4 km massive map with 13 different enchanted lands. Starting with a special destructor in hand, you must survive a 100 player deathmatch! Come battle in this wonderland and craft your own way to victory now!' FROM games WHERE igdb_id = 107922 ON CONFLICT (game_id, language_code) DO NOTHING;
