INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('blast-zone-tournament', 90782, '2018-07-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1ijw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4r9.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blast Zone! Tournament', 'Blast Zone! Tournament is the fast-paced game where fun meets explosive combat! 32 player cross-platform multiplayer either local, online, or combined. Ranked and unranked matches to cater to both casual players and hardcore fans. 10 solo and team-based multiplayer modes including Free-For-All, Team Deathmatch, Bomb Blast, Treasure Mode, King Mode, Zombie Mode and more! Story-driven single-player Challenge Mode with 240 unique challenges. 280 multiplayer levels, with tweakable options including handicaps, lives, starting items, bomber stats, overall match settings, and more. Create individual characters with over 10 billion unlockable cosmetic and gear item combinations. Robust set of social features from friends lists to partying, news, mail, and more to help foster a healthy community and lay the foundations for esports tournaments. Pulsating party soundtrack.' FROM games WHERE igdb_id = 90782 ON CONFLICT (game_id, language_code) DO NOTHING;
