INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mônica e a Guarda dos Coelhos', 'Mônica e a Guarda dos Coelhos is a couch co-op game for one to four players, with a focus on teamwork and cooperation. Featuring the ability to play as a group with (many) heroes from the Brazilian IP Monica and Friends, everyone must have a different role and help to defend the castles against the smudge horde! Use magical bunnies with unique powers, load them into cannons, and fire them at incoming enemies! Monica, Maggy, Jimmy Five, Smudge and their friends from the Lemon Tree Street need your help on a great adventure!' FROM games WHERE igdb_id = 112669 ON CONFLICT (game_id, language_code) DO NOTHING;
