INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Return of the Tentacle', 'Return of the Tentacle: Prologue is a fan-made sequel to the classic LucasArts point and click adventure game Day of the Tentacle. The game takes place two years after the original. Purple Tentacle is back and again tries to conquer the world and enslave humanity. Bernard, Laverne, and Hoagie make their way back to the mansion of the mad scientist Dr. Fred and work on a plan to save the world – by time-traveling once more.' FROM games WHERE igdb_id = 2274 ON CONFLICT (game_id, language_code) DO NOTHING;
