INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DayZ', 'DayZ is a hardcore open-world survival game with only one rule: stay alive, no matter what. How long can you survive a post-apocalyptic world? A land overrun with an infected "zombie" population, where you compete with other survivors for limited resources. Will you team up with strangers and stay strong together? Or play as a lone wolf to avoid betrayal? This is DayZ, this is your story.' FROM games WHERE igdb_id = 2117 ON CONFLICT (game_id, language_code) DO NOTHING;
