INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PUBG Mobile', 'PUBG MOBILE offers the most intense multiplayer battles on your mobile phone. Join the battle, put on your gear, and play to win. Survive in epic 100-player battles in Classic Mode, Payload Mode, the fast-paced 4v4 Team Deathmatch Mode, and Infection Mode. Survival is all that matters. Survive to the end to get the last laugh. Accept missions and fire at will!' FROM games WHERE igdb_id = 95340 ON CONFLICT (game_id, language_code) DO NOTHING;
