INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Neverwinter Nights: Enhanced Edition', 'Neverwinter Nights: Enhanced Edition is an updated version of the 2002 video game Neverwinter Nights. The Enhanced Edition is based on Neverwinter Nights: Diamond Edition and it comes with the base game as well as the Shadows of Undrentide, Hordes of the Underdark, Kingmaker, Witch''s Wake and ShadowGuard expansions. Remastered version brings numerous technological improvements to the game, including an updated graphics engine and revitalized multiplayer support.' FROM games WHERE igdb_id = 23719 ON CONFLICT (game_id, language_code) DO NOTHING;
