INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tale-of-alamar', 87778, '2018-03-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob7ig.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/rhkt8qhtym0q4jz9fpb1.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tale of Alamar', 'In a world where the Leylines of Magic and Planes of Existence converge, follow the adventures of Hiro as you face dangerous beasts, meet fantastical allies, sail the open ocean, and traverse dangerous dungeons filled with puzzles, traps, and hoards of treasure. You begin your story as Hiro, a Paladin traveling the world of Alamar in search of work and purpose. Uncover the plots of the devilish Hell Knights, and forge partnerships with fellow aspiring heroes such as Alotta Fagina the elven ranger, Rhaza the satyr Rogue, and Liri the daughter of ancient druidic clan. Embark on a quest that will take you through several continents and even other Planes as you fight to repel the forces of Darkness that threaten to engulf Alamar. These are the Tales of Alamar.' FROM games WHERE igdb_id = 87778 ON CONFLICT (game_id, language_code) DO NOTHING;
