INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'TT Isle of Man: Ride on the Edge', 'For bikers, there are two types of speed races: the Isle of Man TT and the rest. No race is more difficult. Take up the challenge of the legendary Snaefell Mountain course: all 37.73 miles faithfully reproduced with the champions and their bikes.' FROM games WHERE igdb_id = 81220 ON CONFLICT (game_id, language_code) DO NOTHING;
