INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hifuu-nightmare-diary-violet-detector', 107253, '2018-08-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co27q2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1j3i.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hifuu Nightmare Diary: Violet Detector.', 'Violet Detector, like its predecessors Shoot the Bullet, Double Spoiler and Impossible Spell Card, is a collection of many individual danmaku patterns that the player can choose from at their leisure. In addition to the usual mechanic of taking photographs that clear enemy bullets, Sumireko has several psychic superpowers at her disposal, such as teleportation. The game features all of the characters who debuted in Legacy of Lunatic Kingdom and Hidden Star in Four Seasons, plus Reimu, Marisa, and most of the final and EX bosses from previous games.' FROM games WHERE igdb_id = 107253 ON CONFLICT (game_id, language_code) DO NOTHING;
