INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('senran-kagura-peach-ball', 54521, '2018-12-13', 74, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1om6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arbec.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Senran Kagura Peach Ball', 'Senran Kagura Peach Ball: Clothes shredding brawlers, rhythmic cooking contests, sunny water gun fights or massage therapy – what’s left for the student shinobi of Senran Kagura to do? Well, there’s always pinball! However, Haruka’s “experiments”, conveniently located in the local arcade, have once again caused havoc for the girls. This time her concoction has mentally turned some of her fellow shinobi into animals and the only way to reverse the effects is by using the mystical Peach Ball, which just so happens to fit perfectly in a pinball machine. Plunge into this new adventure and flip, bump, spin, or ricochet the Peach Ball onto the confused shinobi to return them to their normal selves. With customizable tables, special minigames, a story mode, and fan-favorite additional modes including diorama mode and the dressing room, Senran Kagura Peach Ball is set to be one of the hottest pinball games yet.' FROM games WHERE igdb_id = 54521 ON CONFLICT (game_id, language_code) DO NOTHING;
