INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Egypt: Old Kingdom', 'Egypt: Old Kingdom is a turn-based strategy, built on the history of the I-VIII dynasties of Ancient Egypt. Take on the role of tjati - the royal viziers, governing the state on behalf of the great pharaohs. Manage resources, assign workers, found new districts, build temples and palaces and discover the amazing history of Ancient Egypt. Become a witness on more than a hundred historical events that occurred from 3150 to 2150 BC. Develop early state on the banks of the Nile to the Greatest Civilization, which created the Wonder of the Ancient World, survived to this day.' FROM games WHERE igdb_id = 75230 ON CONFLICT (game_id, language_code) DO NOTHING;
