INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dying Light: Bad Blood', 'Dying Light: Bad Blood is a multiplayer expansion set in the Dying Light universe. Bad Blood offers intense and dynamically changing online matches that creatively blend the distinction between PvP and PvE style of gameplay, while retaining the core of what made Dying Light and international success. Inspired by the current battle royal games, its gameplay is planned to have 6 players dropped into a zombie infested area and scavenge for supplies while trying to escape.' FROM games WHERE igdb_id = 76891 ON CONFLICT (game_id, language_code) DO NOTHING;
