INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eternal Card Game', 'Eternal is a free-to-play online collectible card video game developed and published by Dire Wolf Digital. Eternal is currently available for iPhone and iPad iOS devices on the App Store, PCs using Steam, and for Android devices using Google Play. It is also available on Xbox, and Nintendo Switch. The game features cross-platform play, allowing players to use any of the supported platforms to compete with each other.
