INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Casey Powell Lacrosse 18', 'Casey Powell Lacrosse 18 offers sports fans a dynamic, fast, and challenging experience, with all the excitement, speed, and scoring of real-life lacrosse, including a completely reworked series of faceoff, shot, stick and dodging controls. It also features enhanced AI that responds to the complex 6v6 tactics of lacrosse. New motion capture animations for everything from faceoffs and shooting to post-goal celebrations add even further realism to the game.
