INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Objects in Space', 'Objects in Space is a modempunk stealth space-trading game set in Apollo, a huge cluster of star systems dozens of lightyears away from earth. You are a lonesome ship''s captain, buying and selling wares in order to keep your bucket of bolts afloat and stay one step ahead of pirates, organized criminals, corrupt governments and shady laws.' FROM games WHERE igdb_id = 19088 ON CONFLICT (game_id, language_code) DO NOTHING;
