INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pipe by BMX Streets', 'Pipe is a physics based BMX experience built for the BMX community designed to simulate realistic BMX motion. Perform over 50 aerial stunts, grind any corner, send big airs in the Pipe! Pipe also includes some fun Easter Eggs for those willing to explore and think outside the box.' FROM games WHERE igdb_id = 89977 ON CONFLICT (game_id, language_code) DO NOTHING;
