INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alto''s Odyssey', 'Alto’s Odyssey is an endless sandboarding journey set against an ever-changing desert landscape. The game features Alto series hallmarks like fluid physics-based movement, procedurally generated terrain, and dynamic lighting and weather effects. Players will soar above windswept dunes, traverse thrilling canyons, and explore long-hidden temple cities in a fantastical place far from Alto’s home village.' FROM games WHERE igdb_id = 26428 ON CONFLICT (game_id, language_code) DO NOTHING;
