INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mother Simulator', 'It’s a humorous project about a young parent''s difficult weekdays. If you feel worried, irritated, you don’t understand what’s going on and what you must do next, so don’t worry. We want to give you exactly these feelings in our game.' FROM games WHERE igdb_id = 89974 ON CONFLICT (game_id, language_code) DO NOTHING;
