INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eco', 'Enter the world of Eco, a fully simulated ecosystem bustling with thousands of growing plants and animals living their lives. Build, harvest, and take resources from an environment where your every action affects the world around you. An imminent meteor strike threatens global destruction. Can you save the world without destroying it in the process?' FROM games WHERE igdb_id = 34939 ON CONFLICT (game_id, language_code) DO NOTHING;
