INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mobility', 134789, '2018-02-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2ovw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8zmn.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mobility!', 'Mobility! is an acrobatic precision platformer. Platform throughout various levels, while you fall on, slide off, or otherwise touch every block on the level. Every level is part of a larger spaceship, which has broken down in one way or another. It''s up to you to get them back up running as part of your training for the Mobility, an elite-class league of master repairmen. In an age of starships and public space travel, they''re often the saviors when major problems occur. Mobility is designed to appeal to a large range of players: it''s not as punishing as your usual precision platformer.' FROM games WHERE igdb_id = 134789 ON CONFLICT (game_id, language_code) DO NOTHING;
