INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('stickman-skate-battle', 116251, '2018-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1jst.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1pr7.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stickman Skate Battle', 'Pack your skateboard and join the ultimate Stickman Skate Battle multiplayer PVP experience. Battle with your friends and all people around the world in 1vs1 matches in astonishing, beautiful, hand designed skate parks. Perform spectacular tricks and combinations trying to beat your opponent to get his coins and get a chance to participate in the best high stake world events. Daily and weekly tournaments, freeride, 1vs1 matches, challenges and domination are just few of the awesome features waiting for you right now.' FROM games WHERE igdb_id = 116251 ON CONFLICT (game_id, language_code) DO NOTHING;
