INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Adventure Escape: Haunted Hunt', 'On the eve of a grand party, Otto the supernatural hunter reveals his newest catch to his guests: Moira the shapeshifter. Moira must use her supernatural talents to shapeshift into different animals to escape the hunter’s clutches! Explore a seance room, armory, secret vault, and other spooky locations to learn the house’s tragic history! Meet other supernaturals along the way, including a lovable supernatural pup and a ghost out for revenge.' FROM games WHERE igdb_id = 102850 ON CONFLICT (game_id, language_code) DO NOTHING;
