INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tower climber', 'Tower climber is a super simple, excitingly fun and surprisingly addictive game suitable for people of all ages. Simply tap to make the character jump, try to rise as high as you can and don''t fall because it''ll hurt :). Featuring cute pixel-art graphics, this endless arcade will keep the user entertained for hours!INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 90193 AND ge.slug = 'adventure' ON CONFLICT DO NOTHING;
