INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-spirit-of-twelve', 89820, '2018-12-31', NULL, NULL, 'https://images.igdb.com/igdb/image/upload/t_1080p/ahljxctelyklrjnoenzp.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Spirit of Twelve', 'One summer night a mysterious object crash lands in Nidelium, the kingdom where our tale begins. The King and his Wizard retrieves it and returns it to the castle. The wizard inspects it but does not know what it is. He however has an ominous feeling and decides to consult with his guild. That night a thief, looking to steal from the Wizard, seizes the object but mysteriously decides to commits suicide by jumping from the window in the room where the object was kept. The golden band which surrounds the object is ripped off as it crashes on the ground and break in half. The broken shards of the item are empty upon inspection and the wizard decides to takes the ring band, which contains an inscription, to his guild to try and unravel the mystery.' FROM games WHERE igdb_id = 89820 ON CONFLICT (game_id, language_code) DO NOTHING;
